using namespace std;
struct Tile{double x,y;int bd,shape;vector<int> nb,edge;};
struct Row{int own,s1,n1,s2,n2,next;};
struct Genome{vector<Row> rows;vector<pair<int,int>>seed;string lineage;};
struct Result{double score=-1e9,dist=0,radius=0,late=0,straight=0;int steps=0,peak=0,minPop=99999,minBd=99999,period=0,territory=0,usedMask=0;long long sums[4]={};string outcome;};
struct Elite{Genome g;Result r;};
vector<Tile>tiles;vector<unsigned char>statev,mark;vector<array<unsigned char,4>>counts;vector<int>active,candidates,future;vector<pair<int,int>>updates,seedEdges;mt19937_64 rng;long long totalSteps=0,evals=0;unordered_map<string,long long>outcomes;unordered_set<string>reported;
int ri(int n){return rng()%n;}double rf(){return (rng()>>11)*0x1.0p-53;}
uint64_t mix(uint64_t x){x+=0x9e3779b97f4a7c15ULL;x=(x^(x>>30))*0xbf58476d1ce4e5b9ULL;x=(x^(x>>27))*0x94d049bb133111ebULL;return x^(x>>31);}
void init(const Genome&g){for(int i:active)statev[i]=0;active.clear();for(auto[i,s]:g.seed){statev[i]=s;active.push_back(i);}}
void step(const Genome&g,Result&r){candidates.clear();for(int i:active){if(!mark[i]){mark[i]=1;candidates.push_back(i);}for(int j:tiles[i].nb){counts[j][statev[i]]++;if(!mark[j]){mark[j]=1;candidates.push_back(j);}}}future.clear();updates.clear();for(int i:candidates){auto&n=counts[i];n[0]=tiles[i].nb.size()-n[1]-n[2]-n[3];int v=0;for(int k=0;k<(int)g.rows.size();k++){auto row=g.rows[k];if((row.own<0||row.own==statev[i])&&n[row.s1]>=row.n1&&(row.n2==0||n[row.s2]>=row.n2)){v=row.next;r.usedMask|=1<<k;break;}}if(v){future.push_back(i);updates.push_back({i,v});}n={};mark[i]=0;}for(int i:active)statev[i]=0;for(auto[i,s]:updates)statev[i]=s;active.swap(future);}
Result evaluate(const Genome&g,int horizon){init(g);Result r;unordered_map<uint64_t,int>seen;unordered_set<int>territory;double x0=0,y0=0,lastx=0,lasty=0,path=0,cruiseX=0,cruiseY=0;vector<double>distances;for(int t=0;t<=horizon;t++){r.steps=t;if(active.empty()){r.outcome="extinct";break;}double x=0,y=0;uint64_t h=0;for(int i:active){x+=tiles[i].x;y+=tiles[i].y;r.minBd=min(r.minBd,tiles[i].bd);h^=mix(((uint64_t)i<<8)|statev[i]);territory.insert(i);if(t>=30)r.sums[statev[i]]++;}x/=active.size();y/=active.size();if(!t)x0=lastx=x,y0=lasty=y;if(t>=30){r.minPop=min(r.minPop,(int)active.size());if(t==30)cruiseX=x,cruiseY=y;}double rad=0;for(int i:active)rad=max(rad,hypot(tiles[i].x-x,tiles[i].y-y));r.radius=max(r.radius,rad);r.peak=max(r.peak,(int)active.size());r.dist=hypot(x-x0,y-y0);distances.push_back(r.dist);if(t)path+=hypot(x-lastx,y-lasty);lastx=x;lasty=y;if(r.peak>80||r.radius>18){r.outcome="spread";break;}if(r.minBd<5){r.outcome="boundary";break;}if(seen.count(h)){r.period=t-seen[h];r.outcome="cycle";break;}seen[h]=t;if(t==horizon){r.outcome="horizon";break;}step(g,r);}r.territory=territory.size();if(distances.size()>40)r.late=distances.back()-distances[distances.size()-41];r.straight=r.dist/max(path,1e-9);r.score=r.dist*12+min(r.steps,180)*.25-r.radius*8-r.peak*.15+max(r.late,0.0)*3;if(r.outcome=="cycle")r.score-=70;if(r.outcome=="spread")r.score-=180;if((r.outcome=="boundary"||r.outcome=="horizon")&&r.dist>60&&r.straight>.65){r.score+=300; // Prefer additional active states and larger distinct anatomies, not inert rule edits.
 int total=r.sums[1]+r.sums[2]+r.sums[3];double diversity=0;for(int s=1;s<4;s++)if(r.sums[s])diversity+=min(1.0,r.sums[s]/max(1.0,total*.12));r.score+=diversity*50+min(r.minPop,15)*3;}
totalSteps+=r.steps;evals++;outcomes[r.outcome]++;return r;}
bool quiescent(const Row&r){return r.next==0||r.own>0||(r.s1>0&&r.n1>0)||(r.s2>0&&r.n2>0);}
Row randomRow(){Row r;do{r={ri(5)-1,ri(4),1+ri(3),ri(4),ri(2)?0:1+ri(3),ri(4)};}while(!quiescent(r));return r;}
Genome fresh(){Genome g;g.lineage="random";auto[a,b]=seedEdges[ri(seedEdges.size())];g.seed={{a,1+ri(3)},{b,1+ri(3)}};int n=3+ri(6);for(int i=0;i<n;i++)g.rows.push_back(randomRow());return g;}
string signature(const Genome&g){stringstream s;for(auto r:g.rows)s<<r.own<<','<<r.s1<<','<<r.n1<<','<<r.s2<<','<<r.n2<<','<<r.next<<';';s<<'|';for(auto[i,v]:g.seed)s<<i<<':'<<v<<',';return s.str();}
Genome mutate(Genome g){int n=1+ri(3);for(int j=0;j<n;j++){int action=ri(12);if(action<6){int k=ri(g.rows.size());auto r=g.rows[k];if(action==0)r.own=ri(5)-1;if(action==1)r.s1=ri(4);if(action==2)r.n1=1+ri(4);if(action==3)r.s2=ri(4);if(action==4)r.n2=ri(4);if(action==5)r.next=ri(4);if(quiescent(r))g.rows[k]=r;}else if(action==6&&g.rows.size()<10)g.rows.insert(g.rows.begin()+ri(g.rows.size()+1),randomRow());else if(action==7&&g.rows.size()>2)g.rows.erase(g.rows.begin()+ri(g.rows.size()));else if(action==8)swap(g.rows[ri(g.rows.size())],g.rows[ri(g.rows.size())]);else if(action==9)g.seed[ri(g.seed.size())].second=1+ri(3);else if(action==10){auto[a,b]=seedEdges[ri(seedEdges.size())];g.seed={{a,g.seed[0].second},{b,g.seed.back().second}};}else{if(g.seed.size()<6&&rf()<.65){auto[i,v]=g.seed[ri(g.seed.size())];int nb=tiles[i].nb[ri(tiles[i].nb.size())];bool present=false;for(auto[p,s]:g.seed)if(p==nb)present=true;if(!present)g.seed.push_back({nb,1+ri(3)});}else if(g.seed.size()>2)g.seed.erase(g.seed.begin()+ri(g.seed.size()));}}return g;}
void emit(const Genome&g,const Result&r,string kind,long long generation){cout<<"{\"kind\":\""<<kind<<"\",\"evaluation\":"<<evals<<",\"epoch\":"<<generation<<",\"tiling\":\"hat\",\"depth\":5,\"neighborhood\":\"touch\",\"lineage\":\""<<g.lineage<<"\",\"rows\":[";bool first=true;for(auto row:g.rows){if(!first)cout<<',';first=false;cout<<"{\"own\":"<<row.own<<",\"counts\":[["<<row.s1<<','<<row.n1<<"]";if(row.n2)cout<<",["<<row.s2<<','<<row.n2<<"]";cout<<"],\"next\":"<<row.next<<'}';}cout<<"],\"default\":0,\"cellStates\":[";first=true;for(auto[i,s]:g.seed){if(!first)cout<<',';first=false;cout<<'['<<i<<','<<s<<']';}cout<<"],\"score\":"<<r.score<<",\"steps\":"<<r.steps<<",\"outcome\":\""<<r.outcome<<"\",\"displacement\":"<<r.dist<<",\"maximumRadius\":"<<r.radius<<",\"peakPopulation\":"<<r.peak<<",\"minimumCruisePopulation\":"<<r.minPop<<",\"directionality\":"<<r.straight<<",\"lateProgress\":"<<r.late<<",\"minimumBoundary\":"<<r.minBd<<",\"territory\":"<<r.territory<<",\"usedRowsMask\":"<<r.usedMask<<",\"stateSumsAfter30\":["<<r.sums[1]<<','<<r.sums[2]<<','<<r.sums[3]<<"]}"<<endl;}
int main(int argc,char**argv){if(argc<7){cerr<<"touch edge seed epochs evaluationsPerEpoch horizon\n";return 1;}ifstream tf(argv[1]),ef(argv[2]);int N,M;tf>>N;ef>>M;if(N!=M)return 2;tiles.resize(N);for(int i=0;i<N;i++){int n;auto&t=tiles[i];tf>>t.x>>t.y>>t.bd>>t.shape>>n;t.nb.resize(n);for(int&j:t.nb)tf>>j;double x,y;int bd,sh;ef>>x>>y>>bd>>sh>>n;t.edge.resize(n);for(int&j:t.edge)ef>>j;}for(int a=0;a<N;a++)if(tiles[a].bd>=60)for(int b:tiles[a].edge)if(b>a&&tiles[b].bd>=60)seedEdges.push_back({a,b});statev.resize(N);mark.resize(N);counts.resize(N);rng.seed(stoull(argv[3]));int epochs=stoi(argv[4]),per=stoi(argv[5]),horizon=stoi(argv[6]);
vector<Genome>parents;Genome b;b.lineage="derived-SIMPLE";b.rows={{0,1,2,0,0,0},{0,2,1,0,0,1},{1,2,1,0,0,2}};b.seed={{2945,1},{2943,2}};parents.push_back(b);Genome a;a.lineage="derived-Edmond-A";a.rows={{0,2,2,0,0,0},{-1,1,3,0,0,3},{2,1,1,0,1,1},{1,2,1,0,0,3},{0,1,1,0,0,2}};a.seed={{2945,2},{2943,1}};parents.push_back(a);Genome c;c.lineage="derived-Edmond-C";c.rows={{-1,2,1,1,3,3},{1,2,1,0,0,2},{3,3,3,0,0,3},{0,3,2,0,0,1},{-1,2,1,0,0,1}};c.seed={{7267,1},{7283,2}};parents.push_back(c);
for(int epoch=0;epoch<epochs;epoch++){vector<Elite>elites;unordered_set<string>seen;double best=-1e9;for(int trial=0;trial<per;trial++){Genome g;if(trial<3&&epoch%2==0&&(argc<=7||string(argv[7])!="random-only"))g=parents[trial];else if(elites.size()&&rf()<.92){int k=min((int)elites.size()-1,(int)(pow(rf(),1.7)*elites.size()));g=mutate(elites[k].g);}else g=fresh();string sig=signature(g);if(seen.count(sig)){trial--;continue;}seen.insert(sig);Result r=evaluate(g,horizon);if(r.score>best){best=r.score;if(r.dist>30)emit(g,r,"record",epoch);}if(elites.size()<100||r.score>elites.back().r.score){elites.push_back({g,r});sort(elites.begin(),elites.end(),[](auto&a,auto&b){return a.r.score>b.r.score;});if(elites.size()>100)elites.pop_back();}
if(r.dist>120&&r.radius<10&&r.straight>.75&&(r.outcome=="boundary"||r.outcome=="horizon")){// Coarse phenotype buckets retain distinct state/population balances.
stringstream ph;int sum=r.sums[1]+r.sums[2]+r.sums[3];ph<<r.minPop<<','<<r.peak<<','<<int(r.steps?10*r.dist/r.steps:0);for(auto s:r.sums)ph<<','<<int(20.0*s/max(1,sum));if(!reported.count(ph.str())){reported.insert(ph.str());emit(g,r,"candidate",epoch);}}
if(trial&&trial%10000==0)cerr<<"epoch "<<epoch<<" trial "<<trial<<" evaluations "<<evals<<" steps "<<totalSteps<<" best "<<best<<endl;}cerr<<"epoch complete "<<epoch<<" evaluations "<<evals<<" steps "<<totalSteps<<" best "<<best<<endl;for(int k=0;k<min(5,(int)elites.size());k++)emit(elites[k].g,elites[k].r,"elite",epoch);}
cout<<"{\"kind\":\"summary\",\"seed\":"<<argv[3]<<",\"epochs\":"<<epochs<<",\"evaluationsPerEpoch\":"<<per<<",\"horizon\":"<<horizon<<",\"evaluations\":"<<evals<<",\"evolutionSteps\":"<<totalSteps<<",\"distinctReportedBuckets\":"<<reported.size()<<",\"outcomes\":{";bool first=true;for(auto [s,n]:outcomes){if(!first)cout<<',';first=false;cout<<'"'<<s<<"\":"<<n;}cout<<"}}"<<endl;}
